{
    Console.WriteLine("TYPE: " + t.FullName + (t.IsEnum?" (enum)":"") + (t.IsInterface?" (iface)":"") + (t.IsAbstract&&t.IsSealed?" (static)":""));
    if (t.IsEnum) { foreach (var n in Enum.GetNames(t)) Console.WriteLine("   ."+n); continue; }
    foreach (var c in t.GetConstructors()) Console.WriteLine("   ctor(" + string.Join(", ", c.GetParameters().Select(p=>p.ParameterType.Name+" "+p.Name)) + ")");
    foreach (var p in t.GetProperties(BindingFlags.Public|BindingFlags.Instance|BindingFlags.Static)) Console.WriteLine("   prop " + p.PropertyType.Name + " " + p.Name);
    foreach (var m in t.GetMethods(BindingFlags.Public|BindingFlags.Static|BindingFlags.DeclaredOnly)) Console.WriteLine("   static " + m.ReturnType.Name + " " + m.Name + "(" + string.Join(", ", m.GetParameters().Select(p=>p.ParameterType.Name+" "+p.Name)) + ")");
}
EOF
